head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[input > M > setEditFormat]<br/>컴포넌트의 editFormat 속성을 설정합니다.",
    "validation" : [        
        "format(필수) 파라미터로 입력하거나 표시되는 값의 포맷을 마스크 문자로 설정합니다",
        "editFormat 속성을 설정하면 applyFormat=all 로 동작하여 값을 입력중일때와 값이 표시될때 모두 동일 포맷이 적용됩니다.",
        "editFormat 의 마스크 문자가 입력값 형식과 맞지 않으면 정상적으로 표시되지 않습니다.",
        "editFormat 속성에 설정한 포맷이 즉시 입력값에 적용됩니다.",
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



scwin.get_text_edit = function(target) {    
    let rtn = '';
    let tagName = target.tagName

    if (tagName !== "INPUT") {
        rtn = target.textContent
        wf_body_bottom.getObj("scwin").setReturnValue("text : " + rtn);    
    }
    else {
        rtn = target.value
        wf_body_bottom.getObj("scwin").setReturnValue("text : " + rtn);   
    }    
}



scwin.get_text_display = function(target) {    
    let rtn = '';
    let tagName = target.render.tagName

    if (tagName !== "INPUT") {
        rtn = target.render.textContent
        wf_body_bottom.getObj("scwin").setReturnValue("text : " + rtn);    
    }
    else {
        rtn = target.render.value
        wf_body_bottom.getObj("scwin").setReturnValue("text : " + rtn);   
    }    
}



// target1
scwin.btn_setEditFormat1_onclick = function (e) {
    target1.setEditFormat("##AAaaZZzzSS");
    target1.setValue("12AZaz0Z0zaZ");
    // target1.focus();
};

scwin.btn_getText1_onclick = function (e) {
    scwin.get_text_display(target1);
}

